namespace sv_53a780a0db4848c09b3b3e1b7a022fa3.Services;

/// <summary>
/// Scoped service that holds the currently selected warehouse for a single circuit.
/// Components subscribe to <see cref="OnChange"/> to react when the selection changes.
/// Because the service is registered as Scoped, each Blazor Server circuit (i.e. each
/// browser tab / user session) gets its own independent instance.
/// </summary>
public sealed class WarehouseStateService
{
    public static readonly IReadOnlyList<(string Id, string Name)> AvailableWarehouses =
    [
        ("WH-A", "Warehouse A"),
        ("WH-B", "Warehouse B"),
        ("WH-C", "Warehouse C"),
    ];

    private string _currentWarehouseId = AvailableWarehouses[0].Id;

    public string CurrentWarehouseId => _currentWarehouseId;

    public string CurrentWarehouseName =>
        AvailableWarehouses.First(w => w.Id == _currentWarehouseId).Name;

    /// <summary>
    /// Fired whenever the selected warehouse changes.
    /// Subscribers should call <c>InvokeAsync(StateHasChanged)</c> in their handler.
    /// </summary>
    public event Func<Task>? OnChange;

    public async Task SetWarehouseAsync(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId)
            return;

        _currentWarehouseId = warehouseId;

        if (OnChange is not null)
            await OnChange.Invoke();
    }
}

namespace sv_53a780a0db4848c09b3b3e1b7a022fa3.Services;

/// <summary>
/// Scoped service that polls for low-stock alerts on a timer.
/// Any component can subscribe to <see cref="OnAlertCountChanged"/> to be notified
/// when fresh data arrives — even if a different component triggered the poll.
/// </summary>
public sealed class InventoryAlertService : IDisposable
{
    private readonly WarehouseStateService _warehouseState;
    private readonly Random _random = new();
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;

    public int CurrentLowStockCount { get; private set; }

    /// <summary>
    /// Fired after every successful poll so ALL subscribers refresh together.
    /// </summary>
    public event Func<Task>? OnAlertCountChanged;

    public InventoryAlertService(WarehouseStateService warehouseState)
    {
        _warehouseState = warehouseState;
    }

    /// <summary>Simulates a database query — returns a random number 0-15.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Call when a component that needs polling becomes visible.
    /// Ref-counted: the timer runs while at least one subscriber is active.
    /// </summary>
    public void StartPolling()
    {
        _subscriberCount++;

        if (_subscriberCount == 1)
        {
            _cts = new CancellationTokenSource();
            _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
            _ = PollLoopAsync(_cts.Token);
        }
    }

    /// <summary>
    /// Call when a component that needs polling is disposed / hidden.
    /// </summary>
    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);

        if (_subscriberCount == 0)
        {
            CancelTimer();
        }
    }

    /// <summary>
    /// Force an immediate refresh (e.g. after the warehouse selection changes).
    /// </summary>
    public async Task RefreshAsync()
    {
        CurrentLowStockCount = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);

        if (OnAlertCountChanged is not null)
            await OnAlertCountChanged.Invoke();
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Fire once immediately so subscribers don't wait 10 s for the first value.
        await RefreshAsync();

        try
        {
            while (await _timer!.WaitForNextTickAsync(ct))
            {
                await RefreshAsync();
            }
        }
        catch (OperationCanceledException)
        {
            // Expected on disposal / stop.
        }
    }

    private void CancelTimer()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _timer?.Dispose();
        _timer = null;
    }

    public void Dispose() => CancelTimer();
}

