@using sv_53a780a0db4848c09b3b3e1b7a022fa3.Services
@implements IDisposable
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService

<div class="d-flex align-items-center gap-2">
    <label class="text-white mb-0 small fw-bold" for="warehouse-select">Site:</label>
    <select id="warehouse-select"
            class="form-select form-select-sm"
            style="width: auto;"
            value="@WarehouseState.CurrentWarehouseId"
            @onchange="OnWarehouseChanged">
        @foreach (var (id, name) in WarehouseStateService.AvailableWarehouses)
        {
            <option value="@id">@name</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += HandleWarehouseChanged;
    }

    private async Task OnWarehouseChanged(ChangeEventArgs e)
    {
        var newId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(newId))
        {
            await WarehouseState.SetWarehouseAsync(newId);
            // Refresh alerts immediately for the new warehouse.
            await AlertService.RefreshAsync();
        }
    }

    private async Task HandleWarehouseChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= HandleWarehouseChanged;
    }
}

