@inject InventoryAlertService AlertService

<PageTitle>Dashboard — @WarehouseState.CurrentWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card @(AlertService.CurrentLowStockCount > 0 ? "border-danger" : "border-success")">
            <div class="card-body text-center">
                <h5 class="card-title">Low-Stock Alerts</h5>
                <p class="display-4 @(AlertService.CurrentLowStockCount > 0 ? "text-danger" : "text-success")">
                    @AlertService.CurrentLowStockCount
                </p>
                <p class="text-muted small">
                    Items below minimum level at <strong>@WarehouseState.CurrentWarehouseName</strong>
                </p>
                <p class="text-muted small mb-0">Refreshes every 10 seconds</p>
            </div>
        </div>
    </div>

    <div class="col-md-8">
        <div class="card">
            <div class="card-header">Activity Feed — @WarehouseState.CurrentWarehouseName</div>
            <div class="card-body">
                <p class="text-muted">Real-time warehouse activity will appear here.</p>
            </div>
        </div>
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += HandleStateChanged;
        AlertService.OnAlertCountChanged += HandleStateChanged;

        // Start the 10-second polling loop while this page is visible.
        AlertService.StartPolling();
    }

    private async Task HandleStateChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.StopPolling();
        WarehouseState.OnChange -= HandleStateChanged;
        AlertService.OnAlertCountChanged -= HandleStateChanged;
    }
}

